"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["Οι Μογγόλοι κατέλαβαν τη Δαμασκό", "430bdfea"], "d": ["Στη συριακή εκστρατεία του Χουλαγκού η Δαμασκός πέρασε στους Μογγόλους.", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["Μάχη του Αϊν Τζαλούτ: η Δαμασκός και η Ιερουσαλήμ πέρασαν στους Μαμελούκους", "40ebd7b7"], "d": ["Ο Κουτούζ νίκησε τους Μογγόλους στο Αϊν Τζαλούτ (25 Ραμαζανίου 658 / 3 Σεπτεμβρίου 1260)· το μεγαλύτερο μέρος της Συρίας, η Δαμασκός και η Ιερουσαλήμ πέρασαν στα χέρια των Μαμελούκων και η αγιουβιδική δυναστεία έληξε.", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["Ο Μπαϊμπάρς αναβίωσε το αββασιδικό χαλιφάτο στο Κάιρο — η Μέκκα και η Μεδίνα συνδέθηκαν με τους Μαμελούκους", "a5128a1e"], "d": ["Ο Μπαϊμπάρς ανακήρυξε χαλίφη στο Κάιρο τον Αββασίδη Αχμέντ, που είχε σωθεί από την καταστροφή της Βαγδάτης, και του ορκίστηκε πίστη· ως προστάτης του χαλιφάτου συνέδεσε και τους Δύο Ιερούς Τόπους με τη μαμελουκική επικυριαρχία. Η ημέρα είναι εκείνη της αναβίωσης του χαλιφάτου· η ημέρα της σύνδεσης της Μέκκας και της Μεδίνας δεν υπάρχει στην πηγή (κατώτερο όριο).", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["Τα στρατεύματα της Νίκαιας μπήκαν στην Κωνσταντινούπολη — η Βυζαντινή Αυτοκρατορία ιδρύθηκε εκ νέου", "81741490"], "d": ["Τα στρατεύματα της Νίκαιας μπήκαν στην Κωνσταντινούπολη στις 25 Ιουλίου 1261 και έβαλαν τέλος στη λατινική κυριαρχία· τα εδάφη του κράτους των Λάσκαρη (Νίκαιας) — Προύσα, Σμύρνη, Τσίμπε, Αδριανούπολη, Θεσσαλονίκη — έγιναν ξανά Βυζαντινή Αυτοκρατορία. Ο άτλας εμφανίζει την περίοδο της Αυτοκρατορίας της Νίκαιας πριν από το 1261 σε αυτά τα σημεία μόνο για όσα αναφέρονται στην πηγή με το όνομά τους.", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["Ο Κάρολος της Ανδεγαυίας κατέλαβε το Δυρράχιο και την Κρόια", "082a86b8"], "d": ["Ο Κάρολος από τη δυναστεία της Ανδεγαυίας κατέλαβε το 1271-1272 το Δυρράχιο και την Κρόια και ανοικοδόμησε το παλιό κάστρο.", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["Οι Σικελοί κατέλαβαν το νησί των Τζέρμπα", "daab5ad2"], "d": ["Το νησί των Τζέρμπα καταλήφθηκε το έτος 683 (1284-85) από τους Σικελούς· στην αρχή ήταν κτήμα του παπικού θρόνου και στη συνέχεια εξαρτήθηκε από το Βασίλειο της Σικελίας.", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["Τα Ιωάννινα προσαρτήθηκαν ξανά στη Βυζαντινή Αυτοκρατορία", "60016303"], "d": ["Τα Ιωάννινα, που άλλαξαν χέρια πολλές φορές στο δεύτερο μισό του 13ου αιώνα, προσαρτήθηκαν ξανά στο Βυζάντιο το 1318, διατηρώντας ωστόσο ως ένα βαθμό την αυτονομία τους· το κέντρο του Δεσποτάτου της Ηπείρου μετατοπίστηκε στην Άρτα.", "14c24d12"]},
"OLAYLAR_T5_1000B:1334-01-01:0":{"b": ["Οι κάτοικοι των Τζέρμπα έδιωξαν τους Σικελούς από το νησί", "ff71985e"], "d": ["Οι κάτοικοι του νησιού, εξεγερμένοι κατά της κακής διοίκησης των Σικελών διοικητών, έδιωξαν τους Σικελούς το 1334· οι Τζέρμπα πέρασαν ξανά στη διοίκηση των Χαφσιδών.", "1ddb9780"]},
